import{_ as e,o as s,c as r,a2 as t}from"./chunks/framework.BjkiRu3Q.js";const i="/images/cliente/home-storefront.png",g=JSON.parse('{"title":"1. Bienvenido a PayMe Panamá","description":"","frontmatter":{},"headers":[],"relativePath":"cliente/index.md","filePath":"cliente/index.md"}'),o={name:"cliente/index.md"};function n(c,a,d,l,p,u){return s(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="_1-bienvenido-a-payme-panama" tabindex="-1">1. Bienvenido a PayMe Panamá <a class="header-anchor" href="#_1-bienvenido-a-payme-panama" aria-label="Permalink to &quot;1. Bienvenido a PayMe Panamá&quot;">​</a></h1><p>¡Bienvenido a la tienda online de <strong>PayMe Panamá</strong>! Esta guía te enseñará paso a paso cómo comprar de forma rápida, segura y cómoda desde tu teléfono celular o computadora.</p><hr><h2 id="_1-1-¿que-puedes-hacer-en-la-tienda" tabindex="-1">1.1 ¿Qué puedes hacer en la tienda? <a class="header-anchor" href="#_1-1-¿que-puedes-hacer-en-la-tienda" aria-label="Permalink to &quot;1.1 ¿Qué puedes hacer en la tienda?&quot;">​</a></h2><p>En nuestra tienda online puedes:</p><ul><li><strong>Explorar miles de productos:</strong> Tecnología, accesorios, hogar, moda y más.</li><li><strong>Comprar con precios en dólares (USD/PAB):</strong> Con cálculo automático de impuestos de Panamá (<strong>7% ITBMS</strong>).</li><li><strong>Pagar como tú prefieras:</strong> Con <strong>Yappy</strong> de Banco General, tarjetas de crédito/débito Visa o Mastercard, tarjeta Clave o transferencia bancaria ACH.</li><li><strong>Recibir en la puerta de tu casa:</strong> Envíos a Ciudad de Panamá, Panamá Oeste y todas las provincias del interior.</li></ul><hr><h2 id="_1-2-portada-de-la-tienda-pagina-principal" tabindex="-1">1.2 Portada de la Tienda (Página Principal) <a class="header-anchor" href="#_1-2-portada-de-la-tienda-pagina-principal" aria-label="Permalink to &quot;1.2 Portada de la Tienda (Página Principal)&quot;">​</a></h2><p>Al entrar a <a href="https://pyme.rsfsecure.site/" target="_blank" rel="noreferrer">https://pyme.rsfsecure.site/</a> verás la página principal de la tienda:</p><div class="screenshot-box"><div class="screenshot-header"><div class="screenshot-dots"><span class="screenshot-dot red"></span><span class="screenshot-dot yellow"></span><span class="screenshot-dot green"></span></div><span class="screenshot-title">Portada Principal de la Tienda</span><span class="screenshot-url">https://pyme.rsfsecure.site/</span></div><div class="screenshot-body"><img src="'+i+'" alt="Portada Principal de la Tienda"></div></div><hr><h2 id="_1-3-partes-principales-de-la-pantalla" tabindex="-1">1.3 Partes principales de la pantalla <a class="header-anchor" href="#_1-3-partes-principales-de-la-pantalla" aria-label="Permalink to &quot;1.3 Partes principales de la pantalla&quot;">​</a></h2><ol><li><strong>Barra Superior (Siempre a la vista):</strong></li></ol><ul><li><strong>Buscador:</strong> Escribe lo que buscas para ver resultados al instante.</li><li><strong>Mi Cuenta:</strong> Para iniciar sesión, ver tus compras o registrarte.</li><li><strong>Carrito de Compras:</strong> Un icono con bolsa de compras que te indica cuántos artículos llevas y el total a pagar.</li></ul><ol start="2"><li><strong>Banners de Ofertas:</strong> Promociones de temporada, descuentos especiales y artículos con envío gratis.</li><li><strong>Categorías Destacadas:</strong> Botones rápidos para ir directo a la sección que te interesa (Celulares, Computadoras, Audio, etc.).</li><li><strong>Productos Populares:</strong> Los artículos más vendidos y mejor valorados por otros clientes en Panamá.</li></ol><hr><h2 id="guia-rapida-para-comprar-en-la-tienda" tabindex="-1">Guía Rápida para Comprar en la Tienda <a class="header-anchor" href="#guia-rapida-para-comprar-en-la-tienda" aria-label="Permalink to &quot;Guía Rápida para Comprar en la Tienda&quot;">​</a></h2><p>Explora cada etapa del proceso de compra:</p><div class="factus-grid"><a href="/cliente/cuenta" class="factus-card"><div class="factus-card-title">2. Registro, Seguridad y Direcciones <span class="arrow">→</span></div><div class="factus-card-desc">Registro en 1 clic con Google, cambio de contraseña y libreta de direcciones.</div></a><a href="/cliente/catalogo" class="factus-card"><div class="factus-card-title">3. Catálogo y Búsqueda <span class="arrow">→</span></div><div class="factus-card-desc">Búsqueda predictiva instantánea y filtrado por marcas, categorías o precio.</div></a><a href="/cliente/producto" class="factus-card"><div class="factus-card-title">4. Ficha de Producto <span class="arrow">→</span></div><div class="factus-card-desc">Galería de fotos en alta resolución, selección de opciones y disponibilidad.</div></a><a href="/cliente/carrito" class="factus-card"><div class="factus-card-title">5. Carrito de Compras <span class="arrow">→</span></div><div class="factus-card-desc">Gestión de tu bolsa de compras, cantidades y cupones promocionales.</div></a><a href="/cliente/checkout" class="factus-card"><div class="factus-card-title">6. Checkout y Métodos de Pago <span class="arrow">→</span></div><div class="factus-card-desc">Pago en 3 pasos con Yappy, tarjetas Visa/Mastercard, Clave o ACH.</div></a><a href="/cliente/pedidos" class="factus-card"><div class="factus-card-title">7. Seguimiento, Facturas y Devoluciones <span class="arrow">→</span></div><div class="factus-card-desc">Rastreo de envíos, factura fiscal PDF y cómo solicitar cambios o devoluciones.</div></a></div>',19)])])}const h=e(o,[["render",n]]);export{g as __pageData,h as default};
